/** Domain value -> brand colour, generated from the SAME table the
 *  phone's laneColor()/statusColor() use. No surface re-decides this. */
object WearSemantics {
    fun lane(value: String?): Color = when (value) {
        "backlog" -> WearTokens.txtTertiary
        "working" -> WearTokens.ai
        "review" -> WearTokens.human
        "done" -> WearTokens.ok
        else -> WearTokens.txtTertiary
    }

    fun status(value: String?): Color = when (value) {
        "queued" -> WearTokens.txtTertiary
        "running" -> WearTokens.ai
        "needs_you" -> WearTokens.warn
        "submitted" -> WearTokens.human
        "accepted" -> WearTokens.ok
        "bounced" -> WearTokens.danger
        "done" -> WearTokens.ok
        "failed" -> WearTokens.danger
        else -> WearTokens.txtTertiary
    }
}

/** The brand palette mapped onto Wear Material3's colour roles. The
 *  mapping itself is data in ops/tools/gen_tokens.py (WEAR_ROLE), so
 *  "which HelmDeck colour is the primary action" is decided in one
 *  place for every surface.
 *
 *  `background` is the one deliberate non-token: pure black, because a
 *  watch is OLED and an unlit pixel costs nothing. The brand's dark
 *  surfaces still carry the identity - they paint the cards. */
